"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[102],{9102:(e,t,i)=>{i.r(t),i.d(t,{PAPERS:()=>a});let a=[{id:"2610.12572",title:"DiffusionART: Efficient, Stable and Scalable Reinforcement of Diffusion Models",up:226,href:"https://arxiv.org/abs/2610.12572",abstract:"Online reinforcement learning (RL) fine-tunes diffusion models with black-box rewards, but reverse-process methods such as Flow-GRPO are limited in efficiency by poor credit assignment, while forward-process methods such as DiffusionNFT are efficient yet unstable without carefully tuned exponential-moving-average (EMA) off-policy training. We show that NFT-style objectives contain a hidden forward--reverse consistency force that joint positive--negative training cancels only partially, and that EMA stabilizes training through restoration rather than off-policy rollouts. We introduce DiffusionA",pdfUrl:"https://arxiv.org/pdf/2610.12572",primaryCategory:"cs.LG",published:"2026-10-08T00:00:00Z"},{id:"2610.13527",title:"S-Space: Exploring Spatial Workspace in Multimodal Language Models",up:199,href:"https://arxiv.org/abs/2610.13527",abstract:"Multimodal language models (MLLMs) exhibit promising spatial reasoning capabilities, yet the internal mechanisms supporting them remain poorly understood. We uncover S-Space, a linear representation subspace in which object-token representations encode continuous coordinates along horizontal, vertical, and distance axes. Although we identify these axes by differentiating spatial-answer scores with respect to object-token activations, S-Space is intrinsic rather than induced by specific data or prompts, remaining readable under non-spatial questions. We show that S-Space functions as an interna",pdfUrl:"https://arxiv.org/pdf/2610.13527",primaryCategory:"cs.CV",published:"2026-10-09T12:48:41Z"},{id:"2610.12772",title:"Reflex: Visually Grounded Reactive Humanoid Control",up:126,href:"https://arxiv.org/abs/2610.12772",abstract:"Humans effortlessly react to the world; they adeptly return a tennis shot, catch a falling cup, step aside from a passing cart, or pass a box tossed during truck unloading. These everyday actions require anticipating a moving target and reflexively responding with the whole body within about a second. Such visual reactive whole-body control remains challenging for humanoids, which must (1) coordinate whole-body control, (2) react to object dynamics in real time, and (3) ground perception in egocentric vision. We study catching thrown boxes as a representative task that demands all three capabi",pdfUrl:"https://arxiv.org/pdf/2610.12772",primaryCategory:"cs.RO",published:"2026-10-08T00:00:00Z"},{id:"2610.12611",title:"SoftwareGym: Scaling Computer-Use Agent Training with Diverse Synthesized Software Environments",up:82,href:"https://arxiv.org/abs/2610.12611",abstract:"Computer-use agents (CUAs) are rapidly improving, yet synthesizing diverse and reliable software environments at scale remains challenging. Native application environments require substantial construction and integration effort, which limits application coverage and increases the risk of application-specific overfitting. Browser-hosted environments provide limited interaction depth and workflow complexity. These limitations motivate SoftwareGym, an automated pipeline for synthesizing GUI software environments with diverse interfaces, executable functionality, and runtime-verified behavior. It ",pdfUrl:"https://arxiv.org/pdf/2610.12611",primaryCategory:"cs.MA",published:"2026-10-08T00:00:00Z"},{id:"2610.07987",title:"VisionWeave: Weaving Elastic Visual Representations as a Native Capability of MLLMs",up:56,href:"https://arxiv.org/abs/2610.07987",abstract:"Multimodal large language models have become the dominant paradigm for visual understanding, but incur substantial costs by encoding inputs into dense, fixed-size patch tokens. However, visual information is unevenly distributed: some regions require fine-grained detail, while others admit compact representations. Downsampling sacrifices this detail, while existing token pruning and adaptive approaches remain limited in content-adaptive granularity, task generalization, and integration with modern MLLMs and serving infrastructure. Overcoming these limitations calls for foundation models that l",pdfUrl:"https://arxiv.org/pdf/2610.07987",primaryCategory:"cs.CV",published:"2026-10-06T00:00:00Z"},{id:"2609.38748",title:"Here the World in Stereo: Learning Dynamic Spatial Correspondence for Immersive Joint Video-Audio Generation",up:52,href:"https://arxiv.org/abs/2609.38748",abstract:"Recent joint video-audio generation models have achieved strong semantic correspondence and temporal synchronization. However, applications such as AR/VR and interactive gaming further require stereo audio to provide an immersive sense, which remains largely overlooked. Effective stereo audio requires the perceived sound location to evolve consistently with the motion of its corresponding visual source. We refer to this property as Dynamic Spatial Correspondence and propose StereoBind, a framework that binds visual source motion to stereo sound generation. StereoBind uses motion tracks to coor",pdfUrl:"https://arxiv.org/pdf/2609.38748",primaryCategory:"cs.CV",published:"2026-09-30T00:00:00Z"},{id:"2610.12341",title:"Can AI Agents Learn Their Way to the Top? Evaluating Heuristic Learning in a Long-Running Game Agent Competition",up:42,href:"https://arxiv.org/abs/2610.12341",abstract:"Adversarial games have driven advances from heuristic search to reinforcement learning, yet learning and adapting strategies from limited samples remain challenging. AI agents offer an alternative by turning game experience into revisions of executable policies. Building on heuristic learning (HL), we formalize Adversarial Heuristic Learning (AHL), a paradigm that uses AI agents as learning engines to refine game policies and supporting software while keeping model weights fixed. We introduce AAArena, a benchmark comprising 12 authentic adversarial games and 1,920 archived human programs, with",pdfUrl:"https://arxiv.org/pdf/2610.12341",primaryCategory:"cs.AI",doi:"https://doi.org/10.18653/v1/2025.emnlp-main.466",year:2025,openalexId:"https://openalex.org/W4416036585",published:"2026-10-08T00:00:00Z"},{id:"2610.13113",title:"Continually Post-training Small Models via Synthetic Self-distillation",up:40,href:"https://arxiv.org/abs/2610.13113",abstract:"Continual post-training faces a dual challenge of acquisition and retention: models must learn new capabilities while preserving prior knowledge. While Self-Distillation Fine-Tuning (SDFT) mitigates this using self-supervision with in-context demonstrations, it relies on strong in-context learning and instruction-following abilities. Consequently, SDFT fails on smaller models critical for low-latency, on-device use. To enable continual learning at smaller scales, we first identify the root cause of failure. We show that poor acquisition and forgetting correlate linearly with the post-trained m",pdfUrl:"https://arxiv.org/pdf/2610.13113",primaryCategory:"cs.LG",published:"2026-10-09T00:00:00Z"},{id:"2610.11361",title:"SepGen: Multi-Stem Audio-Video Separation and Generation in a Single Model",up:38,href:"https://arxiv.org/abs/2610.11361",abstract:"A 4D audio-visual scene comprises a video, the dynamic geometry it depicts, and the sound sources that populate it, each with its own position and trajectory. Rendering such a scene from a novel viewpoint requires that every source be available as an individual waveform, so that it can be localized in the scene and propagated to the observer before the signals are mixed. Joint audio-video generators can synthesize the video and its soundtrack, but the soundtrack is emitted as a single audio-mix in which the sources are not individually accessible. We present SepGen, which extends a pretrained ",pdfUrl:"https://arxiv.org/pdf/2610.11361",primaryCategory:"cs.SD",published:"2026-10-08T00:00:00Z"},{id:"2610.12984",title:"Work2Skill: Capturing Human GUI Experience for Reusable Agent Skill Induction",up:38,href:"https://arxiv.org/abs/2610.12984",abstract:"Computer-use agents can perform increasingly complex GUI tasks, yet unfamiliar software and workflows requiring human domain knowledge remain challenging. Human demonstrations convey procedural knowledge through the same GUI interaction space, but reuse requires interpreting actions in context and separating workflow rules from task-specific details. We thus introduce Work2Skill, a framework that captures human GUI experience for reusable agent skill induction. WorkRecorder provides the framework's infrastructure for collecting this experience, aligning screen recordings, mouse and keyboard ev",pdfUrl:"https://arxiv.org/pdf/2610.12984",primaryCategory:"cs.AI",published:"2026-10-09T00:00:00Z"},{id:"2610.12570",title:"Contextual Correction of Parallel Draftsfor Speculative Decoding",up:26,href:"https://arxiv.org/abs/2610.12570",abstract:"Speculative decoding accelerates large language model inference by using a lightweight drafter to propose multiple tokens that are subsequently verified in parallel by the target model. Recent diffusion-based drafters make this paradigm particularly attractive: deep attention-based neural backbones provide strong predictions, while drafting multiple future positions in parallel avoids the sequential cost of autoregressive generation. This parallelism, however, comes at a cost. Tokens within a draft block are predicted without access to the realized identities of preceding draft tokens, removin",pdfUrl:"https://arxiv.org/pdf/2610.12570",primaryCategory:"cs.CL",published:"2026-10-08T00:00:00Z"},{id:"2610.12978",title:"Learning Representations to Guide Pixel Diffusion Transformers",up:22,href:"https://arxiv.org/abs/2610.12978",abstract:"Visual representations are largely developed for understanding, yet what makes them useful for generation remains unclear. We study this question in pixel diffusion transformers and uncover two key insights. First, better representation quality does not necessarily translate into greater generative utility, as externally aligned semantics can be progressively lost during pixel synthesis. Second, architectural separation with specialized pixel decoders mainly redistributes semantic and spatial modeling, without necessarily yielding representations better suited to generation. These insights sug",pdfUrl:"https://arxiv.org/pdf/2610.12978",primaryCategory:"cs.CV",published:"2026-10-09T00:00:00Z"},{id:"2609.36641",title:"Inducing Process Supervision from Outcome-Only Reinforcement Learning",up:19,href:"https://arxiv.org/abs/2609.36641",abstract:"Process reward models (PRMs) have become a key component for LLMs, as their step-level feedback supports both post-training and test-time reasoning. However, training strong PRMs remains costly: human step annotation is difficult to scale, while Monte Carlo estimation is computationally expensive and can drift from the intrinsic correctness of steps. To get effective PRMs at low cost, we introduce TIPS (Thinking-Induced Process Supervision), an outcome-only reinforcement learning (RL) framework for training generative PRMs. In TIPS, the model generates a chain-of-thought (CoT) followed by step",pdfUrl:"https://arxiv.org/pdf/2609.36641",primaryCategory:"cs.LG",published:"2026-09-29T00:00:00Z"},{id:"2610.12569",title:"SWE-Duel: Towards a Self-Scaling Arena for Coding Agents",up:18,href:"https://arxiv.org/abs/2610.12569",abstract:"Static coding benchmarks are fixed at release. Over time their tasks leak into training data, and stronger agents eventually saturate them. We argue that a benchmark should instead aim to be self-scaling: its tasks and oracles are created at evaluation time, so no content exists in advance to leak, and its difficulty is set by the participating agents rather than fixed at release. We introduce SWE-Duel, an arena in which two coding agents evaluate each other over mirrored Red-Blue turns. In each turn, the Red agent works on a real repository across three context-isolated sessions. It proposes ",pdfUrl:"https://arxiv.org/pdf/2610.12569",primaryCategory:"cs.CL",published:"2026-10-08T00:00:00Z"},{id:"2610.13944",title:"InstantFusion: A Shared Latent Interface for Heterogeneous Image Generators",up:18,href:"https://arxiv.org/abs/2610.13944",abstract:"Diffusion/flow models have emerged as the de facto paradigms for image generation, giving rise to a diverse family of modern generators with increasingly heterogeneous architectures and representations. Despite their remarkable generation capabilities, the cross-model alignment of latent representations and the consistency of their underlying denoising dynamics remain underexplored. In this work, we uncover an intriguing cross-model compatibility: independently trained generators exhibit similar latent spatial organization, while directly handing off intermediate states between unaligned model",pdfUrl:"https://arxiv.org/pdf/2610.13944",primaryCategory:"cs.CV",published:"2026-10-09T00:00:00Z"},{id:"2610.13947",title:"Towards Physically Grounded Articulated 3D Assets: A Multi-Agent Pipeline and Benchmark",up:18,href:"https://arxiv.org/abs/2610.13947",abstract:"In this paper, we study physically grounded articulated 3D asset generation---moving the goal from reproducing how objects look to capturing how they move and function. Inspired by the literature on procedural and agentic generation, we present Artisan, a system that extends the latest method Articraft by introducing a multi-agent pipeline with physical simulation feedback, enabling comprehensive attributes beyond geometry, appearance, and physically plausible articulation, such as collision-free motion, stability under gravity, and accurate mass and material properties. Furthermore, we constr",pdfUrl:"https://arxiv.org/pdf/2610.13947",primaryCategory:"cs.CV",published:"2026-10-09T00:00:00Z"},{id:"2610.12668",title:"Recurrent Harness for Agentic Continual Learning",up:15,href:"https://arxiv.org/abs/2610.12668",abstract:"Language model agents increasingly operate over long interaction streams, requiring online adaptation to distribution shifts through continual learning. However, existing agent harnesses typically either evolve their states only through forward information flow or rely on additional replay or validation data for harness optimization. To address this, we propose ReHarness, a recurrent harness framework for agentic continual learning that complements forward read and write with backward revision under a strictly online streaming protocol. We ask what information could have been captured differen",pdfUrl:"https://arxiv.org/pdf/2610.12668",primaryCategory:"cs.LG",published:"2026-10-08T00:00:00Z"},{id:"2609.37950",title:"Video-RSI: Recursive Self-Improvement of Video Understanding Agents via Harness Evolution",up:13,href:"https://arxiv.org/abs/2609.37950",abstract:"Video understanding agents acquire evidence through an executable harness that controls what they observe and how they use those observations. However, execution traces contain only the evidence acquired by the current harness, leaving competing explanations for failure unresolved and limiting the basis for self-improvement. We introduce Video-RSI, a framework for recursive self-improvement in which a video understanding agent uses its own language model to revise its harness. Through active video investigation, the model revisits the original training videos to test competing failure explanat",pdfUrl:"https://arxiv.org/pdf/2609.37950",primaryCategory:"cs.AI",published:"2026-09-29T00:00:00Z"},{id:"2610.05014",title:"MetaKernelBench: Measuring GPU Kernel Knowledge Transfer Beyond Code",up:13,href:"https://arxiv.org/abs/2610.05014",abstract:"Recent GPU kernel optimization agents retain what they learn in knowledge bases or as distilled skills. Kernel benchmarks score each attempt's implementation for correctness and speed but leave the reuse value of retained experience unmeasured. We introduce MetaKernelBench, which measures whether experience distilled from an attempt in one kernel domain-specific language (DSL) improves a fresh attempt at the same problem in another. Its 74 problems are fused subgraphs in six families, each posed as a pair of CuTe DSL and TIRx variants that differ only in the DSL. The agent first attempts each ",pdfUrl:"https://arxiv.org/pdf/2610.05014",primaryCategory:"cs.LG",published:"2026-10-04T00:00:00Z"},{id:"2610.06354",title:"GraphDecisionBench: Benchmarking System One Models on Graph Tasks",up:13,href:"https://arxiv.org/abs/2610.06354",abstract:"Large language models (LLMs) are increasingly explored for graph understanding and decision-making, while System One models such as Jev select directly from supplied options. However, the capabilities of System One models on graph-related tasks remain unclear. We introduce GraphDecide, a model-independent benchmark that combines structural task profiles, matched graph-text input contrasts and heuristic-proposal controls to diagnose graph decision performance. We evaluate Jev and related choice-based models alongside language-model baselines, covering fourteen model-interface configurations. Je",pdfUrl:"https://arxiv.org/pdf/2610.06354",primaryCategory:"cs.AI",published:"2026-10-09T00:00:00Z"},{id:"2610.11993",title:"DataVista: Diagnosing Multimodal LLMs on Data Video Understanding",up:13,href:"https://arxiv.org/abs/2610.11993",abstract:"Data video is a media form that integrates data visualization with video narrative, widely adopted in news reporting and business analysis. Compared with general video understanding, data video understanding places greater emphasis on accurately reading data from animated charts, integrating evidence across charts and time, and understanding how narrative organization and visual design communicate information. Yet existing benchmarks target either general videos or static charts, and data video understanding has not been systematically evaluated. We present DataVista, the first benchmark for d",pdfUrl:"https://arxiv.org/pdf/2610.11993",primaryCategory:"cs.CV",published:"2026-10-08T00:00:00Z"},{id:"2609.39566",title:"From Given to Gathered Evidence: Agentic Learning for Longitudinal Medical Reasoning",up:12,href:"https://arxiv.org/abs/2609.39566",abstract:"Foundation models can serve as clinical agents through tool-use harnesses. However, conventional medical benchmarks assess reasoning over preselected evidence rather than the ability to seek it across clinical records and longitudinal imaging. We propose CASE: a series of role-specific Clinical Agents for Seeking Evidence, together with a tool-use harness and an agentic post-training framework for compact vision-language policy models. We further introduce a longitudinal multimodal benchmark built on UK Biobank, comprising 50,401 clinical questions derived from real-world ICD-10-coded diagnose",pdfUrl:"https://arxiv.org/pdf/2609.39566",primaryCategory:"cs.CV",published:"2026-09-30T00:00:00Z"},{id:"2610.12939",title:"Surfing the Activation Wave: Analyzing the Information and Geometry of LLM Hidden States for Speculative Decoding",up:12,href:"https://arxiv.org/abs/2610.12939",abstract:"Decoder hidden states from different layers of large language models (LLMs) often encode complementary information. However, existing speculative decoding methods typically rely on a small set of target-model layers chosen using fixed, position-based heuristics. Selecting an optimal subset of layers is inherently a combinatorial problem, making exhaustive evaluation infeasible even for moderately deep models. In this work, we present a principled framework for multi-layer hidden-state selection for speculative decoding based on two complementary criteria: informativeness, measured through matr",pdfUrl:"https://arxiv.org/pdf/2610.12939",primaryCategory:"cs.CL",published:"2026-10-09T00:00:00Z"},{id:"2610.13181",title:"MixTok: Adaptive Visual Tokenization with Global 1D Tokens and Sparse 2D Refinement",up:12,href:"https://arxiv.org/abs/2610.13181",abstract:"Efficient visual tokenization requires balancing representation compactness with the preservation of fine-grained image content. Conventional grid-based tokenizers allocate tokens uniformly across spatial locations despite non-uniform visual complexity, whereas compact 1D tokenizers aggregate global information but can struggle to preserve local details. We introduce MixTok, a hybrid visual tokenizer that combines a compact 1D global representation with sparse 2D tokens for local refinement. A content-adaptive router ranks candidate locations by refinement priority and determines the number of",pdfUrl:"https://arxiv.org/pdf/2610.13181",primaryCategory:"cs.CV",published:"2026-10-09T00:00:00Z"},{id:"W7171516088",title:"SpecBox: Speculative Sandbox Scheduling for Efficient LLM Agent Serving",up:0,href:"https://doi.org/10.48550/arxiv.2607.23933",crossrefDoi:"https://doi.org/10.1007/978-981-92-4805-6_13",year:2026,openalexId:"https://openalex.org/W7171516088",crossrefIssued:"2026-08-24"},{id:"W7204032694",title:"Do Not Let Sandboxes Sit Idle: Cross-Agent Sandbox Re-allocation for LLM Agents",up:0,href:"https://doi.org/10.1007/978-981-92-4805-6_13",doi:"https://doi.org/10.1007/978-981-92-4805-6_13",year:2026,openalexId:"https://openalex.org/W7204032694"},{id:"W7221316450",title:"FHIR-AgentEval: a modular sandbox for benchmarking clinical LLM agents with memory-augmented configurations",up:0,href:"https://doi.org/10.1038/s41746-026-03348-0",doi:"https://doi.org/10.1038/s41746-026-03348-0",year:2026,openalexId:"https://openalex.org/W7221316450"}]}}]);